function smallestWorstGap(nums: number[], p: number): number {
  const a = [...nums].sort((x, y) => x - y);
  const n = a.length;
  // best[i][k]: first i values, k pairs
  const best: number[][] = Array.from({ length: n + 1 }, () => new Array(p + 1).fill(Infinity));
  for (let i = 0; i <= n; i++) best[i][0] = 0;
  for (let i = 2; i <= n; i++) {
    for (let k = 1; k <= p; k++) {
      const pairHere = Math.max(best[i - 2][k - 1], a[i - 1] - a[i - 2]);
      best[i][k] = Math.min(best[i - 1][k], pairHere);
    }
  }
  return best[n][p];
}

