function smallestWorstGap(nums: number[], p: number): number {
  const a = [...nums].sort((x, y) => x - y);
  const n = a.length;
  const pairsWithin = (limit: number): number => {
    let count = 0;
    for (let i = 0; i + 1 < n; ) {
      if (a[i + 1] - a[i] <= limit) {
        count++;
        i += 2;
      } else i++;
    }
    return count;
  };
  let lo = 0, hi = a[n - 1] - a[0];
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (pairsWithin(mid) >= p) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

